"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["60341"],{5579(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>u,frontMatter:()=>o,contentTitle:()=>c,toc:()=>l,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/onboarding/endpoints/onboarding-update-validate","title":"Validate participant update","description":"Production call. Confirms a participant update by presenting the SMS passcode and the transactionId returned by /v2/participant/update.","source":"@site/docs/nhcx/v1/api/onboarding/endpoints/onboarding-update-validate.mdx","sourceDirName":"nhcx/v1/api/onboarding/endpoints","slug":"/nhcx/v1/api/onboarding/endpoints/onboarding-update-validate","permalink":"/docs/pr-48/docs/nhcx/v1/api/onboarding/endpoints/onboarding-update-validate","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Validate participant update","sidebar_label":"Validate participant update","sidebar_class_name":"api-method api-method--get","description":"Production call. Confirms a participant update by presenting the SMS passcode and the transactionId returned by /v2/participant/update.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-onboarding.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Validate participant creation","permalink":"/docs/pr-48/docs/nhcx/v1/api/onboarding/endpoints/onboarding-validate"},"next":{"title":"Overview","permalink":"/docs/pr-48/docs/nhcx/v1/api/adjudicator/"}}'),i=a(62540),r=a(43023),s=a(52563),p=JSON.parse('{"id":"onboarding_update_validate","module":"Onboarding","moduleId":"onboarding","kind":"operation","method":"GET","path":"/update/validate","server":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","servers":[{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production, Participant service. This call is for production."}],"summary":"Validate participant update","title":"Validate participant update","description":"Production call. Confirms a participant update by presenting the SMS passcode and the transactionId returned by /v2/participant/update.\\n\\n### Business purpose\\n\\nChanging a participant\'s encryption certificate or callback endpoint changes where encrypted claims data is delivered and who can decrypt it, so the registry does not apply such updates on an API call alone. /v2/participant/update stages the change and sends a passcode to the registered mobile number; this call confirms it. It is step 4 of the production onboarding sequence and the same approval mechanism protects every later certificate or bridge rotation done through the v2 update.\\n\\n### When to use\\n\\nCall it in production after `/v2/participant/update` returns a `transactionid` and the passcode arrives by SMS, within 24 hours. It makes the new certificate and callback URL live. The production address is `https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate`.\\n\\n### Preconditions\\n\\n- The participant was created and confirmed through `/validate`.\\n- You have the `transactionid` from the update call and its SMS passcode.\\n- You have a valid access token.\\n\\n### Postconditions\\n\\nThe new certificate and callback URL become live. Other participants now fetch the new certificate.\\n\\n### Common mistakes\\n\\n- Assuming the update is live before this call succeeds.\\n- Using a passcode from an earlier update attempt.\\n- Calling `/validate` instead. That one confirms creation.\\n\\n### Best practices\\n\\n- Rotate keys in two phases: keep the old private key available for decrypting inbound callbacks until the update is validated and cached certificates (24-hour TTL on the payer side) have refreshed.\\n- Persist transactionid with its 24-hour expiry and record who completed validation, for audit.\\n- Never log the passcode; treat it as a one-time credential.\\n- After success, call /participant/search on your own code to confirm encryption_cert and endpoint_URL reflect the change.\\n\\n### Related scenario\\n\\nA year after go-live a payer\'s security team rotates the encryption key pair. The integrator generates a new self-signed X.509 certificate, Base64-encodes it and calls /v2/participant/update with participantcode and encryptioncert. The registry returns status and a new transactionid and sends a passcode to the registered mobile. Within the hour the team calls GET /update/validate with both values; on 200 the new certificate is live. Providers that cached the old certificate pick up the new one at their next 24-hour refresh, and the payer keeps the old private key for one more day to decrypt in-flight callbacks.\\n\\n### Specification\\n\\nChapter [Your certificate](/docs/nhcx/v1/getting-started/your-certificate) of the NHCX integration specification.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[{"name":"Accept","required":true,"description":"Always `application/json` on the participant service.","example":"application/json","type":"string"}],"pathParams":[],"queryParams":[{"name":"transactionId","required":true,"description":"","type":"string","example":"<transaction id>"},{"name":"passcode","required":true,"description":"","type":"string","example":"<passcode>"}],"body":[],"responses":[{"status":"200","description":"HTTP 200 with a bare string body (operation particiapntUpdateValidate, response type string).","example":{"_contentType":"string","_body":"<confirmation string as declared by the OpenAPI 200 response>"},"synthesised":false,"fields":[{"name":"_contentType","type":"string","required":false,"description":""},{"name":"_body","type":"string","required":false,"description":""}]}],"curl":"curl --request GET \\\\\\n  --url \\"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\" \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request GET \\\\\\n  --url \\"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\" \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Accept: application/json\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.get(\\n    \\"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Accept\\": \\"application/json\\",\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\", {\\n  method: \\"GET\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Accept\\": \\"application/json\\",\\n  },\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Accept\\", \\"application/json\\")\\n    .method(\\"GET\\", HttpRequest.BodyPublishers.noBody())\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'GET\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Accept: application/json\',\\n    ],\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n)\\n\\nfunc main() {\\n\\treq, err := http.NewRequest(\\"GET\\", \\"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\", nil)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Accept\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"GET\\"), \\"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Headers.TryAddWithoutValidation(\\"Accept\\", \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice/update/validate?transactionId=<TRANSACTIONID>&passcode=<PASSCODE>\')\\nrequest = Net::HTTP::Get.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Accept\'] = \'application/json\'\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let o={title:"Validate participant update",sidebar_label:"Validate participant update",sidebar_class_name:"api-method api-method--get",description:"Production call. Confirms a participant update by presenting the SMS passcode and the transactionId returned by /v2/participant/update.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-onboarding.yaml",generated:!0},c,d={},l=[];function h(e){return(0,i.jsx)(s.Ay,{operation:p})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}}}]);